    "kind": "dev",
    "methods": {
      "absorb(address,uint256,uint256)": {
        "details": "Import a page of the log of the drafts module this Safe used before,      so an author who stays at the same Safe address keeps their drafts      when they adopt new modules.      `offset`/`limit` select one page of the OLD log, one Safe transaction      per page: a whole log does not fit in one transaction, and a Safe      proposal has to. What a page costs is `limit` genesis plus every      version each of them has, so the caller picks the page size.      A genesis this module already knows is skipped, which is what makes a      second call with the same page import nothing twice. Imported      versions keep their cid and their old timestamp, in the old order,      and are written with `blockNumber = 0`.      **`blockNumber` 0 means \"imported, no block recorded\".** The block a      version was first written in is on the old module, not here, and the      import does not copy it (it cannot: `history` returns timestamps and      cids only). A pre-upgrade entry reads 0 for the same reason. A gate      or reader that needs a block for an entry must fall back for those      entries — to the timestamp, or to the old module — rather than read 0      as block 0 of a chain.      `oldModule` is not trusted and cannot make this call revert: every      read of it is a raw `staticcall` whose answer is bounds-checked word      by word (`_oldGenesisList`, `_oldHistory`), and a module that fails,      has no such function, or answers with something that is not the      `fetchAllPaged`/`history` shape is skipped, not fatal. The batch only      keeps going, so one broken genesis in an old log does not strand the      rest. What is not tolerated is this module's own invariants: an      imported version must have a non-empty cid and a timestamp that fits      the stored width, or its genesis is skipped whole.      The loop is bounded twice over — by the page's length and by the data      the old module actually returned — so a lying module cannot make this      iterate or allocate past what it sent."
      },
      "append(bytes32,string)": {
        "details": "Append a version to `genesis`'s log. The first append binds the      genesis to this Safe (and to the insertion-ordered list); later      appends only add a version. There is no edit, no replace, no delete."
      },
      "blocksOf(bytes32)": {
        "details": "The block numbers behind `history`'s timestamps, index for index:      `blocksOf(g)[i]` is the block that wrote `history(g).timestamps[i]`.      A separate call rather than a third return value of `history`, so the      existing read keeps its shape, and a reader that does not care about      blocks pays nothing for them.      `0` is a pre-upgrade or an imported entry: no block was recorded      here, and the timestamp is still authoritative — a gate that needs a      block must fall back for those, not read 0 as a block number. Never      reverts on an unknown genesis."
      },
      "constructor": {
        "custom:oz-upgrades-unsafe-allow": "constructor"
      },
      "fetch(bytes32)": {
        "details": "Latest version of `genesis`. Deliberately does **not** revert on an      unknown genesis: it returns a zeroed Entry whose `versionCount` is 0,      so a caller tests `versionCount == 0` instead of catching a revert."
      },
      "history(bytes32)": {
        "details": "All versions of `genesis`, oldest first. `timestamps` stays      `uint256[]` because that is the ABI callers already read; the      narrower stored value is widened on the way out."
      },
      "proxiableUUID()": {
        "details": "Implementation of the ERC1822 {proxiableUUID} function. This returns the storage slot used by the implementation. It is used to validate the implementation's compatibility when performing an upgrade. IMPORTANT: A proxy pointing at a proxiable contract should not be considered proxiable itself, because this risks bricking a proxy that upgrades to it, by delegating to itself until out of gas. Thus it is critical that this function revert if invoked through a proxy. This is guaranteed by the `notDelegated` modifier."
      },
      "supportsInterface(bytes4)": {
        "details": "EIP-165 role signalling. The id is a compile-time constant of the      deployed contract: it is the answer a reader discovers the role by, so      once published it may never change — a silent change makes every      already-published module undiscoverable, because no registry exists to      correct. `pure` and no storage read, so it cannot fail and cannot be      made to answer differently by an upgrade's storage."
      },
      "upgradeTo(address)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      },
      "upgradeToAndCall(address,bytes)": {
        "custom:oz-upgrades-unsafe-allow-reachable": "delegatecall",
        "details": "Upgrade the implementation of the proxy to `newImplementation`, and subsequently execute the function call encoded in `data`. Calls {_authorizeUpgrade}. Emits an {Upgraded} event."
      }
    },
    "stateVariables": {
      "SEL_FETCH_ALL_PAGED": {
        "details": "The two reads `absorb` asks an old module for. Selectors, not a typed      interface: the answer is decoded by hand, so what the old module      claims to return is never trusted to fit a type defined here."
      },
      "WORD": {
        "details": "One EVM word. Every offset in the untrusted reads below is measured      in these."
      }
    },
